import {clamp,dist,seeded,segmentCircle,angleDelta} from './premium-utils.js';
export const DOODLE_SHAPES=[{id:'wall',name:'Wall',cost:12},{id:'shield',name:'Shield',cost:24},{id:'turret',name:'Turret',cost:35},{id:'shock',name:'Electric trap',cost:28},{id:'slow',name:'Slow field',cost:30},{id:'star',name:'Power aura',cost:40},{id:'mine',name:'Landmine',cost:32},{id:'healer',name:'Healer',cost:38}];
export function recognizeStroke(raw){if(raw.length<4)return null;const p=[raw[0]];for(const q of raw)if(dist(p.at(-1),q)>4)p.push(q);if(p.length<4)return null;const xs=p.map(p=>p.x),ys=p.map(p=>p.y),w=Math.max(...xs)-Math.min(...xs),h=Math.max(...ys)-Math.min(...ys),len=p.slice(1).reduce((s,q,i)=>s+dist(q,p[i]),0);if(len<35||Math.max(w,h)<25||len>2600)return null;const c={x:(Math.min(...xs)+Math.max(...xs))/2,y:(Math.min(...ys)+Math.max(...ys))/2},close=dist(p[0],p.at(-1))<Math.max(w,h)*.28;let turns=0,angles=[];for(let i=2;i<p.length;i++){const a=Math.atan2(p[i-1].y-p[i-2].y,p[i-1].x-p[i-2].x),b=Math.atan2(p[i].y-p[i-1].y,p[i].x-p[i-1].x);turns+=angleDelta(b,a);angles.push(angleDelta(b,a));}let winding=0;for(let i=1;i<p.length;i++)winding+=angleDelta(Math.atan2(p[i].y-c.y,p[i].x-c.x),Math.atan2(p[i-1].y-c.y,p[i-1].x-c.x));
 if(Math.abs(winding)>Math.PI*3&&!close)return 'slow';
 const simplify=(a,epsilon)=>{if(a.length<3)return a;const s=a[0],z=a.at(-1);let max=0,index=0;for(let i=1;i<a.length-1;i++){const dx=z.x-s.x,dy=z.y-s.y,t=clamp(((a[i].x-s.x)*dx+(a[i].y-s.y)*dy)/(dx*dx+dy*dy||1),0,1),d=Math.hypot(a[i].x-s.x-dx*t,a[i].y-s.y-dy*t);if(d>max){max=d;index=i;}}return max>epsilon?[...simplify(a.slice(0,index+1),epsilon).slice(0,-1),...simplify(a.slice(index),epsilon)]:[s,z];};
 const simple=simplify(p,Math.max(w,h)*.07),corners=simple.length-1;const radii=p.map(q=>dist(q,c)),avg=radii.reduce((s,r)=>s+r,0)/radii.length,variance=Math.sqrt(radii.reduce((s,r)=>s+(r-avg)**2,0)/radii.length)/avg;
 if(close&&Math.abs(winding)>4.2){if(corners>=8&&variance>.25)return 'star';if(corners>=3&&corners<=4&&variance>.16)return 'turret';if(variance<.3&&w/h>.5&&w/h<2)return 'shield';if(corners>=7)return 'star';}
 if(close&&corners>=8&&len/Math.max(w,h)>3.5)return 'star';
 if(!close&&corners>=4&&corners<=12){let flips=0,last=0;for(let i=2;i<simple.length;i++){const a=simple[i-2],b=simple[i-1],c=simple[i],cross=(b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x),sign=Math.sign(cross);if(last&&sign!==last)flips++;last=sign;}if(flips>=2)return 'shock';}
 if(!close&&len/dist(p[0],p.at(-1))<1.4)return 'wall';return null;}
const pagePlans=[
 ['First Scribble',[320],['walker']],['Double Margin',[190,440],['walker','runner']],['Paper Planes',[120,310,510],['walker','flyer','walker']],['Armored Ink',[140,475],['armor','walker','runner']],['The Eraser King',[280,470],['shielded','walker','flyer']],
 ['Sprint Notes',[100,250,450],['runner','runner','breaker','walker']],['Winged Footnotes',[180,380,540],['flyer','walker','shielded']],['Shield School',[110,220,350],['shielded','armor','runner']],['Low Road',[290,425,535],['breaker','walker','armor','flyer']],['Multiplication Page',[130,310,510],['splitter','shielded','runner']],
 ['Top of the Class',[95,205,480],['flyer','flyer','armor','runner']],['Three Bad Ideas',[175,335,530],['breaker','splitter','shielded']],['Fast & Heavy',[145,270,455],['runner','armor','runner','shielded']],['Wing Commander',[105,365,515],['flyer','shielded','flyer','breaker']],['The Ink Colossus',[245,390,540],['armor','splitter','shielded','runner']],
 ['Margin Marathon',[95,285,490],['runner','splitter','flyer','runner','breaker']],['The Long Division',[165,300,445,540],['shielded','breaker','armor','flyer']],['Spiral Bound',[120,255,385,520],['splitter','armor','flyer','shielded']],['Final Draft',[100,220,410,535],['breaker','runner','flyer','splitter','armor']],['The Last Page',[95,240,375,535],['shielded','splitter','breaker','flyer','armor','runner']]
];
export const DOODLE_LEVELS=pagePlans.map(([name,paths,composition],i)=>({id:i+1,name,waves:3+Math.floor(i/5),paths,ink:150+Math.floor(i/4)*15,boss:i%5===4,composition}));
const enemies={walker:{hp:60,speed:27,damage:10,reward:15},runner:{hp:38,speed:52,damage:8,reward:12},flyer:{hp:40,speed:36,damage:10,reward:15,flying:true},armor:{hp:140,speed:20,damage:20,reward:25,armor:.5},breaker:{hp:115,speed:29,damage:40,reward:23},shielded:{hp:90,speed:27,damage:13,reward:23,shield:45},splitter:{hp:70,speed:29,damage:11,reward:20,split:true},boss:{hp:650,speed:13,damage:65,reward:100,armor:.25}};
export class DoodleModel{
 constructor({level=1,difficulty=3,mode='story',seed=42}={}){this.kind='doodle';this.levelId=level;this.level=DOODLE_LEVELS[(level-1)%20];this.difficulty=difficulty;this.mode=mode;this.rng=seeded(seed);this.phase='play';this.clock=0;this.duration=mode==='creative'||mode==='endless'?Infinity:180000;this.done=false;this.complete=false;this.ink=mode==='puzzle'?105:this.level.ink;this.maxInk=mode==='creative'?999:240;this.baseHP=250;this.wave=0;this.spawned=0;this.kills=0;this.hits=0;this.mistakes=0;this.points=0;this.items=[];this.enemies=[];this.projectiles=[];this.healing=[];this.effects=[];this.pointers=new Map();this.tool='draw';this.selectedShape='turret';this.nextWave=mode==='creative'?Infinity:2500;this.events=[];this.feedback='Choose a defense, then draw it your way. Its job follows your choice, not its outline.';this.history=[];}
 create(shape,points,owner=0){if(!DOODLE_SHAPES.some(s=>s.id===shape))return false;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),x=xs.reduce((a,b)=>a+b,0)/xs.length,y=ys.reduce((a,b)=>a+b,0)/ys.length,size=clamp(Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys)),35,200),cost=Math.round(DOODLE_SHAPES.find(s=>s.id===shape).cost*(.65+(shape==='wall'?points.slice(1).reduce((s,p,i)=>s+dist(p,points[i]),0):size)/130));if(x<90||x>860||y<60||y>570){this.feedback='Keep drawings in the notebook area between the entry tabs and base.';return false;}if(cost>this.ink){this.feedback='Ink is refilling. Try a smaller drawing or wait.';return false;}this.ink-=cost;this.hits++;const item={shape,x,y,r:size/2,points:points.map(p=>({...p})),hp:shape==='wall'?140:shape==='shield'?260:90,maxHP:shape==='shield'?260:shape==='wall'?140:90,owner,level:1,cost,cooldown:0,expires:shape==='star'?this.clock+15000:Infinity};this.items.push(item);this.history.push(item);this.feedback=DOODLE_SHAPES.find(s=>s.id===shape).name+' created! '+cost+' ink.';this.events.push('draw');return true;}
 input(kind,x,y,id,owner=0){if(this.done)return false;if(kind==='down'){if(this.tool==='upgrade'){const item=this.items.find(b=>dist(b,{x,y})<b.r+18);if(item&&this.ink>=25&&item.level<3){this.ink-=25;item.level++;item.hp+=70;item.maxHP+=70;this.feedback='Defense upgraded to level '+item.level;return true;}return false;}if(this.tool==='place')return this.create(this.selectedShape,[{x:x-25,y:y-25},{x:x+25,y:y+25}],owner);this.pointers.set(id,{points:[{x,y}],owner,shape:this.selectedShape});return true;}const p=this.pointers.get(id);if(!p)return false;if(kind==='move'){if(p.points.length<600&&dist(p.points.at(-1),{x,y})>3)p.points.push({x,y});return true;}this.pointers.delete(id);if(kind==='cancel')return true;p.points.push({x,y});const shape=p.shape;const created=this.create(shape,p.points,p.owner);if(created)this.items.at(-1).handDrawn=true;return created;}
 action(id){if(id==='undo'){const b=this.history.pop();if(!b||!this.items.includes(b))return false;this.items=this.items.filter(x=>x!==b);this.ink=Math.min(this.maxInk,this.ink+b.cost*Math.min(1,b.hp/b.maxHP));return true;}if(id==='next'&&this.mode==='creative'){this.nextWave=this.clock;return true;}if(id==='finish'&&this.mode==='creative'){this.done=true;return true;}if(id.startsWith('shape:')){this.selectedShape=id.slice(6);this.tool='place';return true;}return false;}
 spawn(kind){const type=enemies[kind],lane=this.level.paths[this.spawned%this.level.paths.length];this.enemies.push({...type,kind,x:25,y:lane,hp:type.hp*(.7+this.difficulty*.12),maxHP:type.hp,shield:type.shield||0,cooldown:0,id:this.clock+this.spawned});this.spawned++;}
 damage(e,n,type='normal'){if(e.shield>0){const used=Math.min(e.shield,n);e.shield-=used;n-=used;}e.hp-=n*(type==='shock'?1:1-(e.armor||0));if(e.hp<=0&&!e.dead){e.dead=true;this.kills++;this.points+=e.reward*10;this.ink=Math.min(this.maxInk,this.ink+e.reward*.6);this.events.push('pop');if(e.split){for(const dy of [-16,16])this.enemies.push({...enemies.runner,kind:'runner',x:e.x,y:e.y+dy,hp:24,maxHP:24,cooldown:0});}}}
 blocked(e,b){return b.shape==='wall'&&b.points.slice(1).some((p,i)=>segmentCircle(b.points[i],p,e,17))||b.shape==='shield'&&dist(e,b)<b.r+14;}
 step(dt){if(this.done)return;this.clock+=dt;const t=dt/1000,regen=this.mode==='puzzle'?1.6:this.mode==='creative'?50:5.5-this.difficulty*.45;this.ink=Math.min(this.maxInk,this.ink+regen*t);if(this.clock>=this.nextWave){this.wave++;this.spawned=0;this.quota=5+this.wave+Math.floor(this.levelId/4);this.nextSpawn=this.clock;this.nextWave=Infinity;}if(this.spawned<(this.quota||0)&&this.clock>=this.nextSpawn){const boss=(this.mode==='boss'||this.level.boss)&&this.wave>=this.level.waves&&this.spawned===0;this.spawn(boss?'boss':this.level.composition[(this.spawned+this.wave)%this.level.composition.length]);this.nextSpawn=this.clock+Math.max(500,1300-this.difficulty*110);}
 const alive=this.enemies.filter(e=>e.hp>0);for(const e of alive){let speed=e.speed*(.7+this.difficulty*.13),slow=this.items.some(b=>b.hp>0&&b.shape==='slow'&&dist(b,e)<b.r+65);if(slow)speed*=.35;const next={x:e.x+speed*t,y:e.y},wall=!e.flying&&this.items.find(b=>b.hp>0&&this.blocked(next,b));if(wall){const above=wall.y-wall.r-28,below=wall.y+wall.r+28,way=Math.abs(e.y-above)<Math.abs(e.y-below)?above:below;if(e.kind!=='breaker'&&way>65&&way<565){const dodge={x:e.x,y:e.y+Math.sign(way-e.y)*speed*t};if(!this.items.some(b=>b.hp>0&&this.blocked(dodge,b)))e.y=dodge.y;}if(this.clock>=e.cooldown){wall.hp-=e.damage;e.cooldown=this.clock+800;}}else e.x=next.x;if(e.x>=915){this.baseHP-=e.damage;e.hp=0;e.dead=true;this.events.push('bad');}}
 for(const b of this.items){if(b.hp<=0)continue;if(this.clock>b.expires){b.hp=0;continue;}if(b.shape==='mine'&&alive.some(e=>e.hp>0&&dist(e,b)<b.r+28)){for(const e of alive)if(e.hp>0&&dist(e,b)<125+b.level*15)this.damage(e,125*b.level,'shock');b.hp=0;this.effects.push({x:b.x,y:b.y,kind:'blast',life:450});this.events.push('pop');continue;}if(b.shape==='healer'&&this.clock>=b.cooldown){const targets=this.items.filter(a=>a!==b&&a.hp>0&&a.hp<a.maxHP&&dist(a,b)<260);const target=targets.sort((a,z)=>a.hp/a.maxHP-z.hp/z.maxHP)[0]||(this.baseHP<250&&dist(b,{x:925,y:325})<260?{home:true,x:925,y:325}:null);if(target){this.healing.push({x:b.x,y:b.y,target,amount:22*b.level,life:2000});b.cooldown=this.clock+900;}}if(b.shape==='turret'&&this.clock>=b.cooldown){const target=alive.filter(e=>e.hp>0&&dist(b,e)<210+b.level*25).sort((a,c)=>dist(a,b)-dist(c,b))[0];if(target){const n=dist(target,b)||1,boost=this.items.some(a=>a.shape==='star'&&a.hp>0&&dist(a,b)<200)?1.6:1;this.projectiles.push({x:b.x,y:b.y,vx:(target.x-b.x)/n*430,vy:(target.y-b.y)/n*430,damage:23*b.level*boost,life:1500});b.cooldown=this.clock+Math.max(260,800-b.level*110);}}if(b.shape==='shock'&&this.clock>=b.cooldown){const inRange=alive.filter(e=>e.hp>0&&dist(b,e)<b.r+55);if(inRange.length){for(const e of inRange)this.damage(e,24*b.level,'shock');b.cooldown=this.clock+750;}}if(b.shape==='star'&&this.clock>=b.cooldown){for(const e of alive)if(e.hp>0&&dist(e,b)<b.r+110)this.damage(e,20,'shock');b.cooldown=this.clock+500;}}
 for(const p of this.healing){const target=p.target;if(!target.home&&!this.items.includes(target)){p.life=0;continue;}const distance=dist(p,target),step=300*t;p.life-=dt;if(distance<=step+8){if(target.home)this.baseHP=Math.min(250,this.baseHP+p.amount);else if(target.hp>0)target.hp=Math.min(target.maxHP,target.hp+p.amount);this.effects.push({x:target.x,y:target.y,kind:'heal',life:350});p.life=0;}else{p.x+=(target.x-p.x)/distance*step;p.y+=(target.y-p.y)/distance*step;}}this.healing=this.healing.filter(p=>p.life>0);this.effects=this.effects.filter(e=>(e.life-=dt)>0).slice(-80);for(const p of this.projectiles){const old={x:p.x,y:p.y};p.x+=p.vx*t;p.y+=p.vy*t;p.life-=dt;const target=alive.find(e=>e.hp>0&&segmentCircle(old,p,e,e.kind==='boss'?36:18));if(target){this.damage(target,p.damage);p.life=0;}}this.projectiles=this.projectiles.filter(p=>p.life>0);this.enemies=this.enemies.filter(e=>e.hp>0);this.items=this.items.filter(b=>b.hp>0);if(!this.enemies.length&&this.spawned>=this.quota&&this.nextWave===Infinity){if(this.wave>=this.level.waves&&!['endless','creative'].includes(this.mode)){this.complete=this.done=true;this.events.push('finish');}else{this.nextWave=this.mode==='creative'?Infinity:this.clock+5500;if(this.mode==='creative')this.quota=Infinity;this.ink=Math.min(this.maxInk,this.ink+35);this.feedback='Wave cleared! Reinforce, upgrade or draw a new strategy.';}}if(this.baseHP<=0&&this.mode!=='creative'||this.clock>=this.duration){this.baseHP=Math.max(0,this.baseHP);this.done=true;}}
 update(dt){let left=dt;while(left>0&&!this.done){const t=Math.min(left,16.667);this.step(t);left-=t;}}cancel(){this.pointers.clear();}dispose(){this.cancel();}get score(){return Math.max(0,this.points+this.wave*100+this.baseHP*2+(this.complete?600:0));}summary(){return{completed:this.complete,waves:this.wave,kills:this.kills,base:this.baseHP,defenses:this.hits};}
}
